#include "umicom/debug/view_state.h"
#include <stdio.h>
#include <string.h>
UmiStatus umi_debug_view_state_build(const UmiDebugService*s,const UmiDebugController*c,UmiDebugViewState*out){UmiDebugServiceSnapshot a;UmiDebugControllerSnapshot b;UmiStatus status;if(s==NULL||c==NULL||out==NULL)return UMI_STATUS_INVALID_ARGUMENT;status=umi_debug_service_snapshot(s,&a);if(status==UMI_STATUS_OK)status=umi_debug_controller_snapshot(c,&b);if(status!=UMI_STATUS_OK)return status;(void)memset(out,0,sizeof(*out));(void)snprintf(out->state,sizeof(out->state),"%s",umi_debug_controller_state_text(b.state));out->configurations=a.launch_configuration_count;out->breakpoints=a.breakpoint_count;out->sessions=a.session_count;out->threads=a.thread_count;out->frames=a.stack_frame_count;out->scopes=a.scope_count;out->variables=a.variable_count;out->watches=a.watch_count;out->console_entries=a.console_entry_count;out->modules=a.module_count;out->sources=a.source_count;out->exceptions=a.exception_count;out->events=a.event_count;out->active_thread_id=b.active_thread_id;out->active_frame_id=b.active_frame_id;out->revision=a.revision>b.revision?a.revision:b.revision;return UMI_STATUS_OK;}
